import sys,os
sys.path.append(os.path.abspath(os.path.dirname(__file__) + '/..' + '/..'))

import requests

from config.config import BASE_URL

class SimilarityServiceClient:
    def __init__(self, base_url: str=BASE_URL):
        self.base_url = base_url

    def get_similarity(self, text: str, parent_kb_ids: list, query_mode: int = 3, query_size: int = 10):
        headers = {'Content-Type': 'application/json'}
        data = {
            "text": text,
            "parentKbIds": parent_kb_ids,
            "queryMode": query_mode,
            "querySize": query_size
        }

        try:
            response = requests.post(f'{self.base_url}/similarity/smartCerebellumSimilarity', json=data, headers=headers)
            response.raise_for_status()
            return response.json()
        except Exception as e:
            print(e)
            return {
                'data':{
                    'resultList':[],
                }
            }

# Usage example
if __name__ == '__main__':
    from pprint import pprint
    client = SimilarityServiceClient(base_url='http://kb-data.polymas.com')
    result = client.get_similarity("跃迁", ["Rz5ETbubKH"], query_size=3)
    pprint(result)
